def is_bipartite(n, adj):
    color = [-1] * n  # -1 no team yet, 0 and 1 the two teams

    for s in range(n):
        if color[s] != -1:
            continue
        color[s] = 0
        queue = deque([s])
        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if color[v] == -1:
                    color[v] = 1 - color[u]
                    queue.append(v)
                elif color[v] == color[u]:
                    return False
    return True

def is_bipartite_dfs(n, adj):
    color = [-1] * n

    def dfs(u, c):
        color[u] = c
        for v in adj[u]:
            if color[v] == -1:
                if not dfs(v, 1 - c):
                    return False
            elif color[v] == c:
                return False
        return True

    for s in range(n):
        if color[s] == -1 and not dfs(s, 0):
            return False
    return True

