def topo_dfs(n, adj):
    state = [0] * n  # 0 new, 1 on the path, 2 done
    order = []

    def dfs(u):
        state[u] = 1
        for v in adj[u]:
            if state[v] == 1:
                return False
            if state[v] == 0 and not dfs(v):
                return False
        state[u] = 2
        order.append(u)
        return True

    for u in range(n):
        if state[u] == 0 and not dfs(u):
            return []
    return order[::-1]

def topo_kahn(n, adj):
    indeg = [0] * n
    for u in range(n):
        for v in adj[u]:
            indeg[v] += 1
    queue = deque(u for u in range(n) if indeg[u] == 0)
    order = []
    while queue:
        u = queue.popleft()
        order.append(u)
        for v in adj[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                queue.append(v)
    return order if len(order) == n else []

def count_groups(n, edges):
    parent = list(range(n))  # each node starts as its own root
    rank = [0] * n

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])  # path compression
        return parent[x]

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra == rb:
            return False  # already connected: the edge closes a cycle
        if rank[ra] < rank[rb]:
            ra, rb = rb, ra
        parent[rb] = ra  # the shorter tree goes under the taller
        if rank[ra] == rank[rb]:
            rank[ra] += 1
        return True

    groups = n
    for a, b in edges:
        if union(a, b):
            groups -= 1
    return groups

