def kruskal(n, edges):
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]  # path halving
            x = parent[x]
        return x

    tree, cost = [], 0
    for w, a, b in sorted(edges):
        ra, rb = find(a), find(b)
        if ra == rb:
            continue  # would close a cycle
        parent[rb] = ra
        tree.append((a, b))
        cost += w
        if len(tree) == n - 1:
            break
    return cost, tree

def prim(n, adj):
    seen = [False] * n
    heap = [(0, 0, -1)]  # (weight, node, reached from)
    tree, cost = [], 0
    while heap:
        w, u, p = heapq.heappop(heap)
        if seen[u]:
            continue  # a cheaper edge reached u first
        seen[u] = True
        cost += w
        if p >= 0:
            tree.append((p, u))
        for v, wv in adj[u]:
            if not seen[v]:
                heapq.heappush(heap, (wv, v, u))
    return cost, tree

