def dijkstra(n, adj, src):
    dist = [float('inf')] * n
    prev = [-1] * n
    dist[src] = 0
    heap = [(0, src)]
    while heap:
        d, u = heapq.heappop(heap)
        if d > dist[u]:
            continue  # stale: u was reached more cheaply
        for v, w in adj[u]:
            if d + w < dist[v]:
                dist[v] = d + w  # relax: a shorter way to v
                prev[v] = u
                heapq.heappush(heap, (dist[v], v))
    return dist, prev

