def zero_one_bfs(n, adj, src):
    dist = [float('inf')] * n
    dist[src] = 0
    dq = deque([src])
    while dq:
        u = dq.popleft()
        for v, w in adj[u]:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                if w == 0:
                    dq.appendleft(v)  # as close as u: the front
                else:
                    dq.append(v)  # one step further: the back
    return dist

import heapq

def a_star(grid, start, goal):
    rows, cols = len(grid), len(grid[0])
    def h(cell):  # Manhattan distance: never more than the real cost
        return abs(cell[0] - goal[0]) + abs(cell[1] - goal[1])
    g = {start: 0}
    prev = {start: None}
    heap = [(h(start), h(start), 0, start)]  # (f, h, g, cell): equal f, nearer the goal first
    while heap:
        f, _, d, cell = heapq.heappop(heap)
        if cell == goal:
            return d  # the goal's first pop is optimal
        if d > g[cell]:
            continue  # stale: cell was reached more cheaply
        r, c = cell
        for nb in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
            nr, nc = nb
            if not (0 <= nr < rows and 0 <= nc < cols) or grid[nr][nc]:
                continue  # off the grid, or a wall
            nd = d + 1
            if nd < g.get(nb, float('inf')):
                g[nb] = nd
                prev[nb] = cell
                heapq.heappush(heap, (nd + h(nb), h(nb), nd, nb))
    return -1

def bellman_ford(n, edges, src):
    dist = [float('inf')] * n
    prev = [-1] * n
    dist[src] = 0
    for i in range(n - 1):
        changed = False
        for u, v, w in edges:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w  # relax
                prev[v] = u
                changed = True
        if not changed:
            break  # a quiet round: every distance is final
    for u, v, w in edges:
        if dist[u] + w < dist[v]:
            return None  # still improving: a negative cycle
    return dist, prev
